BEGIN;

-- Missing elements (not in original 62-element insert_data.sql)

-- Reference energies for formation enthalpy calculation
CREATE TABLE IF NOT EXISTS pure_element_reference (
    pure_ref_id SERIAL PRIMARY KEY,
    element_symbol VARCHAR(5) NOT NULL UNIQUE REFERENCES element(symbol),
    oqmd_entry_id INTEGER,
    ground_state_spacegroup VARCHAR(30),
    energy_per_atom DOUBLE PRECISION,  -- eV/atom (delta_e from OQMD)
    volume_per_atom DOUBLE PRECISION,  -- Angstrom^3/atom
    stability DOUBLE PRECISION,  -- eV/atom above hull
    band_gap DOUBLE PRECISION,  -- eV
    n_polymorphs INTEGER,
    source TEXT DEFAULT 'OQMD'
);

CREATE INDEX IF NOT EXISTS idx_pure_ref_symbol ON pure_element_reference(element_symbol);


























































































-- Formation enthalpy view: computes corrected ΔH_f using pure element references
CREATE OR REPLACE VIEW formation_enthalpy AS
SELECT 
    m.entry_id,
    m.formula,
    m.reduced_formula,
    ps.formation_energy_per_atom AS formation_enthalpy_ev_per_atom,
    ps.energy_above_hull,
    ps.is_stable,
    s.prototype,
    s.strukturbericht,
    s.space_group,
    s.lattice_a,
    (SELECT SUM(c2.atomic_fraction * per.energy_per_atom)
     FROM composition c2
     JOIN pure_element_reference per ON per.element_symbol = c2.element
     WHERE c2.entry_id = m.entry_id
    ) AS weighted_ref_energy,
    ps.formation_energy_per_atom - COALESCE(
        (SELECT SUM(c2.atomic_fraction * per.energy_per_atom)
         FROM composition c2
         JOIN pure_element_reference per ON per.element_symbol = c2.element
         WHERE c2.entry_id = m.entry_id
        ), 0
    ) AS corrected_formation_enthalpy
FROM material_entry m
JOIN phase_stability ps ON ps.entry_id = m.entry_id
LEFT JOIN structure s ON s.entry_id = m.entry_id
WHERE m.number_of_elements >= 2;

COMMIT;